<?php
namespace App\Controllers; use App\Core\{Controller,Auth}; use App\Models\User; use App\Services\AuditLogger; class AuthController extends Controller{public function loginForm(){ $this->view('auth/login',['title'=>'ورود']); } public function login(){ $this->requireCsrf();$d=$this->input();$u=(new User)->byLogin($d['login']??''); if(!$u||!password_verify($d['password']??'',$u['password']))$this->json(['ok'=>false,'message'=>'اطلاعات ورود نادرست است.'],422); Auth::login(['id'=>$u['id'],'name'=>$u['first_name'].' '.$u['last_name'],'role'=>$u['role']]); AuditLogger::log('login','users',$u['id']);$this->json(['ok'=>true,'redirect'=>'/']);} public function logout(){AuditLogger::log('logout');Auth::logout();header('Location:/login');} public function forgot(){ $this->view('auth/forgot',['title'=>'بازیابی رمز عبور']);}}
